if(!exists('decision_policy_backtest',mode='function'))library(creditratingsystem)
dv_hash<-if(exists('.cr_hash'))get('.cr_hash')else getFromNamespace('.cr_hash','creditratingsystem')
dv_D<-'2023-01-01';dv_E<-'2024-01-02'
dv_target<-function()list(event='default',horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='initially_performing')
dv_policy<-function(cutoff=.05)compile_credit_decision_policy(list(schema_version='1.0',policy_id=paste0('p',cutoff),version='1',approval_reference='bank-reference',known_at=dv_D,effective_from=dv_D,effective_until='2024-01-01',default_action='DECLINE',missing_action='BLOCKED',target=dv_target(),fields=list('risk.pd'=list(type='number')),rules=list(list(rule_id='approve',priority=1L,action='APPROVE',reason_code='PD_CUTOFF',when=list(list(field='risk.pd',op='le',value=cutoff))))))$value
dv_sources<-function(pd){timing<-list(as_of=dv_D,known_at=dv_D);list(risk=c(timing,list(pd=pd,target=dv_target(),freshness='CURRENT')),affordability=c(timing,list(status='AFFORDABLE')),eligibility=c(timing,list(status='ELIGIBLE')),operations=c(timing,list(status='CLEAR')))}
dv_offer<-function(id,profit=10)list(offer_id=id,version='1',known_at=dv_D,currency='EUR',target=dv_target(),risk_conditioning='CONDITIONAL_ON_THIS_ACCEPTED_OFFER',assumption_reference='scenario',support_status='SUPPORTED',takeup_probability=.5,conditional_booked_expected_loss=2,conditional_booked_npv=profit,ead=100,offer_cost=1)
dv_fixture<-function(){
 policies<-list(list(candidate_id='a',policy=dv_policy(.05),offer_rule_reference='rule-a'),list(candidate_id='b',policy=dv_policy(.2),offer_rule_reference='rule-b'));cases<-lapply(c('one','two'),function(id)list(case_id=id,decision_date=dv_D,weight=1,split_id='validation',prediction_reference='held-out',excluded_from_model_training=TRUE,excluded_from_calibration=TRUE));inputs<-list();for(p in policies)for(i in 1:2)inputs[[length(inputs)+1L]]<-c(list(candidate_id=p$candidate_id,case_id=cases[[i]]$case_id),dv_sources(c(.01,.1)[i]),list(offer=dv_offer(cases[[i]]$case_id),nonapproval_costs=list(REFER=2,DECLINE=0,BLOCKED=0)))
 outcomes<-list(list(case_id='one',funded=TRUE,complete=TRUE,booked_offer_hash=dv_hash(dv_offer('one')),funded_at=dv_D,funding_known_at=dv_D,outcome_end='2024-01-01',known_at=dv_E,defaulted=TRUE,economic_loss=50,net_profit=-40),list(case_id='two',funded=FALSE,complete=FALSE,booked_offer_hash=NULL,funded_at=NULL,funding_known_at=NULL,outcome_end=NULL,known_at=NULL,defaulted=NULL,economic_loss=NULL,net_profit=NULL))
 profile<-list(profile_id='selection',version='1',known_at=dv_D,currency='EUR',registered_at=dv_D,outcome_access_date=dv_E,evaluation_role='VALIDATION',prediction_design='HELD_OUT',split_id='validation',data_fingerprint='bank-declared-data',target=dv_target(),candidate_hashes=setNames(lapply(policies,dv_hash),c('a','b')),objective='expected_npv_per_application',constraints=list(list(constraint_id='loss',metric='expected_loss_per_application',operator='le',threshold=.75)),tie_break='candidate_id',tolerance=1e-12,loss_bounds=list(0,100),profit_bounds=list(-100,100))
 list(policy_candidates=policies,cases=cases,candidate_inputs=inputs,observed_outcomes=outcomes,evaluation_profile=profile,evaluation_cutoff=dv_E)
}
fixture<-function(){kw<-dv_fixture();for(i in seq_along(kw$candidate_inputs))kw$candidate_inputs[[i]]$offer$contract_terms<-list(limit=100,annual_rate=.1,tenor_days=365,currency='EUR');kw$observed_outcomes[[1]]$booked_offer_hash<-dv_hash(kw$candidate_inputs[[1]]$offer);grid<-do.call(evaluate_decision_grid,kw)$value;d<-list(model_id='policy-validation',model_version='1',parameter_version='1',data_fingerprint=kw$evaluation_profile$data_fingerprint,population_id='applications',split_id='validation',prediction_origin='HOLDOUT',evaluation_cutoff=kw$evaluation_cutoff,currency='EUR',target=kw$evaluation_profile$target);rows<-lapply(1:2,function(i){c<-kw$cases[[i]];t<-grid$candidates[[1]]$decisions[[i]];approved<-t$action=='APPROVE';list(prediction_id=c$case_id,entity_id=c$case_id,cluster_id=c$case_id,segment='retail',case_id=c$case_id,weight=1,as_of=c$decision_date,forecast_known_at=c$decision_date,horizon_end='2024-01-01',model_id=d$model_id,model_version='1',parameter_version='1',historical_candidate_id='a',historical_decision=t$decision,offered=approved,taken_up=approved,offered_limit=if(approved)100 else NULL,booked_amount=if(approved)80 else NULL,stages_known_at='2023-01-01',application_cost=2,cost_known_at='2023-01-02',cost_complete=TRUE)});list(evaluated_grid=grid,grid_inputs=kw,historical_cases=rows,design=d,reference_candidate_id='a')}
kw<-fixture();r<-do.call(decision_policy_backtest,kw)$value;stopifnot(r$metrics$factual$funded_rate==.5,r$metrics$factual$observed_pd==1,r$metrics$factual$mean_application_cost==2,r$metrics$paired_candidate_minus_reference[['b|approval_rate']]==.5,r$metrics$paired_candidate_minus_reference[['b|expected_npv_per_application']]==2,r$violation_counts$CANDIDATE_SCENARIO_CONSTRAINT_VIOLATED==1,is.null(r$counterfactual$full_policy_causal_value))
kw<-fixture();kw$historical_cases[[1]]$booked_amount<-120;r<-do.call(decision_policy_backtest,kw)$value;stopifnot(r$violation_counts$BOOKED_LIMIT_EXCEEDED==1)
kw<-fixture();kw$grid_inputs$candidate_inputs[[3]]$offer$contract_terms$limit<-200;kw$evaluated_grid<-do.call(evaluate_decision_grid,kw$grid_inputs)$value;r<-do.call(decision_policy_backtest,kw)$value;stopifnot(is.null(r$candidate_observed_scopes$b$observed_pd),r$candidate_observed_scopes$b$case_status[[1]]$status=='DIFFERENT_BOOKED_OFFER')
kw<-fixture();kw$grid_inputs$observed_outcomes[[2]]$defaulted<-FALSE;stopifnot(inherits(try(do.call(decision_policy_backtest,kw),silent=TRUE),'try-error'))
kw<-fixture();kw$historical_cases[[1]]$stages_known_at<-'2024-02-01';r<-do.call(decision_policy_backtest,kw)$value;stopifnot(r$metrics$factual$funded_rate==0,r$metrics$factual$visible_stage_weight==1)
kw<-fixture();kw$evaluated_grid$candidates[[1]]$metrics$approval_rate<-1;kw$evaluated_grid$sha256<-NULL;kw$evaluated_grid$sha256<-dv_hash(kw$evaluated_grid);stopifnot(do.call(decision_policy_backtest,kw)$value$violation_counts$FROZEN_GRID_RECONCILIATION==1)
kw<-fixture();kw$uncertainty<-'cluster_bootstrap';kw$cluster_resamples<-list(list('one','one'),list('two','two'));r<-do.call(decision_policy_backtest,kw)$value;ci<-r$uncertainty$intervals[['b|expected_npv_per_application']];stopifnot(abs(ci$lower-.1)<1e-12,abs(ci$upper-3.9)<1e-12);cat('Native policy backtest PASS\n')
kw<-fixture();for(i in seq_along(kw$grid_inputs$policy_candidates)){s<-kw$grid_inputs$policy_candidates[[i]]$policy$specification;s$schema_version<-'1.1';s$fields[['operations.legal_status']]<-list(type='category',values=list('VERIFIED','UNVERIFIED'));s$approval_contract<-list(domain='RETAIL_CREDIT',affordability=list(mode='REQUIRED'),required_gates=list(list(field='operations.legal_status',value='VERIFIED')));kw$grid_inputs$policy_candidates[[i]]$policy<-compile_credit_decision_policy(s)$value};kw$grid_inputs$evaluation_profile$candidate_hashes<-setNames(lapply(kw$grid_inputs$policy_candidates,dv_hash),c('a','b'));for(i in seq_along(kw$grid_inputs$candidate_inputs))kw$grid_inputs$candidate_inputs[[i]]$operations$legal_status<-'VERIFIED';kw$evaluated_grid<-do.call(evaluate_decision_grid,kw$grid_inputs)$value;for(i in 1:2)kw$historical_cases[[i]]$historical_decision<-kw$evaluated_grid$candidates[[1]]$decisions[[i]]$decision;r<-do.call(decision_policy_backtest,kw)$value;stopifnot(kw$historical_cases[[1]]$historical_decision$approval_domain=='RETAIL_CREDIT');kw$grid_inputs$candidate_inputs[[1]]$operations$legal_status<-'UNVERIFIED';kw$evaluated_grid<-do.call(evaluate_decision_grid,kw$grid_inputs)$value;kw$historical_cases[[1]]$historical_decision<-kw$evaluated_grid$candidates[[1]]$decisions[[1]]$decision;stopifnot(do.call(decision_policy_backtest,kw)$value$violation_counts$OFFER_WITHOUT_POLICY_APPROVAL==1)
kw<-fixture();s<-kw$grid_inputs$policy_candidates[[1]]$policy$specification;s$known_at<-'2022-01-01';s$effective_from<-'2022-01-01';s$effective_until<-'2023-01-01';kw$grid_inputs$policy_candidates[[1]]$policy<-compile_credit_decision_policy(s)$value;kw$grid_inputs$evaluation_profile$candidate_hashes<-setNames(lapply(kw$grid_inputs$policy_candidates,dv_hash),c('a','b'));kw$evaluated_grid<-do.call(evaluate_decision_grid,kw$grid_inputs)$value;for(i in 1:2)kw$historical_cases[[i]]$historical_decision<-kw$evaluated_grid$candidates[[1]]$decisions[[i]]$decision;stopifnot(do.call(decision_policy_backtest,kw)$value$violation_counts$HISTORICAL_POLICY_NOT_EFFECTIVE==2)
kw<-fixture();kw$historical_cases[[1]]$stages_known_at<-'2025-01-01';kw$historical_cases[[1]]$booked_amount<-120;stopifnot(is.null(do.call(decision_policy_backtest,kw)$value$violation_counts$BOOKED_LIMIT_EXCEEDED));kw<-fixture();kw$historical_cases[[2]]$entity_id<-'one';stopifnot(inherits(try(do.call(decision_policy_backtest,kw),silent=TRUE),'try-error'))
kw<-fixture();kw$grid_inputs$evaluation_profile$constraints[[1]]$threshold<-2;kw$evaluated_grid<-do.call(evaluate_decision_grid,kw$grid_inputs)$value;r<-do.call(decision_policy_backtest,kw)$value;stopifnot(identical(names(r$violation_counts),character()),r$decision$status=='NOT_ASSESSED')

first_draw_fixture<-function(){kw<-fixture();g<-kw$grid_inputs;t<-g$evaluation_profile$target;t$event<-'first_default';t$performance_origin<-'first_draw_at';g$evaluation_profile$target<-t;g$evaluation_profile$target_contract_version<-'1.1';for(i in seq_along(g$policy_candidates)){s<-g$policy_candidates[[i]]$policy$specification;s$target<-t;g$policy_candidates[[i]]$policy<-compile_credit_decision_policy(s)$value};g$evaluation_profile$candidate_hashes<-setNames(lapply(g$policy_candidates,dv_hash),c('a','b'));for(i in seq_along(g$candidate_inputs)){g$candidate_inputs[[i]]$risk$target<-t;g$candidate_inputs[[i]]$offer$target<-t};g$observed_outcomes[[1]]$booked_offer_hash<-dv_hash(g$candidate_inputs[[1]]$offer);kw$grid_inputs<-g;kw$evaluated_grid<-do.call(evaluate_decision_grid,g)$value;for(i in 1:2)kw$historical_cases[[i]]$historical_decision<-kw$evaluated_grid$candidates[[1]]$decisions[[i]]$decision;t$performance_origin<-NULL;kw$design$target<-t;kw$design$policy_target_contract_version<-'1.1';kw$design$performance_origin<-'first_draw_at';kw}
legacy<-fixture();stopifnot(is.null(legacy$grid_inputs$evaluation_profile$target_contract_version),do.call(decision_policy_backtest,legacy)$value$metrics$factual$observed_pd==1)
kw<-first_draw_fixture();original<-kw$grid_inputs$policy_candidates;r<-do.call(decision_policy_backtest,kw)$value;stopifnot(r$metrics$factual$observed_pd==1,r$metrics$factual$funded_rate==.5,identical(original,kw$grid_inputs$policy_candidates),kw$evaluated_grid$profile$target$event=='first_default',select_constrained_policy(kw$evaluated_grid)$value$selected_candidate_id=='a')
for(pair in list(c('policy_target_contract_version','1.0'),c('policy_target_contract_version','9'),c('performance_origin','application_at'))){bad<-kw;bad$design[[pair[[1]]]]<-pair[[2]];stopifnot(inherits(try(do.call(decision_policy_backtest,bad),silent=TRUE),'try-error'))}
for(v in list(c('1.0','first_default','first_draw_at'),c('9','first_default','first_draw_at'),c('1.1','delinquency','first_draw_at'),c('1.1','first_default','application_at'))){bad<-kw$grid_inputs;bad$evaluation_profile$target_contract_version<-v[[1]];bad$evaluation_profile$target$event<-v[[2]];bad$evaluation_profile$target$performance_origin<-v[[3]];stopifnot(inherits(try(do.call(evaluate_decision_grid,bad),silent=TRUE),'try-error'))}
